import pandas as pd

def cs_rank(values):
    s = pd.Series(values, dtype=float)
    n = len(s)
    if n == 1:
        return [0.5]
    r = s.rank()   # 1 to n, ties averaged
    return ((r - 1) / (n - 1)).tolist()

