widget.solution:
import numpy as np

def cs_zscore(values):
    x = np.asarray(values, dtype=float)
    if len(x) < 2 or x.std(ddof=1) == 0:
        return np.zeros(len(x))
    return (x - x.mean()) / x.std(ddof=1)
